lead.source = lead.source && typeof lead.source === 'object' ? lead.source : {};
lead.contact = lead.contact && typeof lead.contact === 'object' ? lead.contact : {};
lead.business = lead.business && typeof lead.business === 'object' ? lead.business : {};
lead.request = lead.request && typeof lead.request === 'object' ? lead.request : {};
lead.processing = lead.processing && typeof lead.processing === 'object' ? lead.processing : {};
lead.metadata = lead.metadata && typeof lead.metadata === 'object' ? lead.metadata : {};

const clean = (value) => value == null || String(value).trim() === '' ? null : String(value).trim();
const normalizePhone = (value) => {
  const raw = clean(value);
  if (!raw) return null;
  let compact = raw.replace(/[\s\-().]/g, '');
  if (compact.startsWith('00')) compact = `+${compact.slice(2)}`;
  const hadPlus = compact.startsWith('+');
  const digits = compact.replace(/\D/g, '');
  if (!digits) return null;
  if (/^01\d{9}$/.test(digits)) return `+20${digits.slice(1)}`;
  if (/^20\d{10}$/.test(digits)) return `+${digits}`;
  if (hadPlus && digits.length >= 8 && digits.length <= 15) return `+${digits}`;
  if (digits.length >= 8 && digits.length <= 15) return `+${digits}`;
  return null;
};
const phoneRaw = clean(lead.contact.phone_raw);
const emailRaw = clean(lead.contact.email_raw);
lead.contact.phone_raw = phoneRaw;
lead.contact.email_raw = emailRaw;
lead.contact.phone_normalized = normalizePhone(phoneRaw);
lead.contact.email_normalized = emailRaw ? emailRaw.toLowerCase() : null;
lead.processing.current_workflow = 'WF02_validation_identity';
lead.processing.updated_at = new Date().toISOString();
lead.audit_events = Array.isArray(lead.audit_events) ? lead.audit_events : [];
lead.audit_events.push({
  lead_id: lead.lead_id ?? null,
  event_type: 'normalized',
  workflow_name: 'WF02_validation_identity',
  execution_id: $execution.id,
  payload: { phone_present: Boolean(phoneRaw), email_present: Boolean(emailRaw) },
  created_at: new Date().toISOString()
});
return [{ json: lead }];

const lead = JSON.parse(JSON.stringify($json ?? {}));
lead.contact = lead.contact && typeof lead.contact === 'object' ? lead.contact : {};
lead.business = lead.business && typeof lead.business === 'object' ? lead.business : {};
lead.processing = lead.processing && typeof lead.processing === 'object' ? lead.processing : {};
const missing = [];
const invalid = [];
const text = (value) => value == null ? '' : String(value).trim();
const name = text(lead.contact.name);
const service = text(lead.business.service_interest);
const phone = text(lead.contact.phone_normalized);
const email = text(lead.contact.email_normalized);
const phoneValid = phone === '' || /^\+[1-9]\d{7,14}$/.test(phone);
const emailValid = email === '' || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
if (!name) missing.push('contact.name');
if (!phone && !email) missing.push('contact.phone_normalized_or_email_normalized');
if (!service) missing.push('business.service_interest');
if (!phoneValid) invalid.push('contact.phone_normalized');
if (!emailValid) invalid.push('contact.email_normalized');
if (lead.contact.consent !== true) invalid.push('contact.consent');
const validationStatus = invalid.length ? 'invalid' : missing.length ? 'incomplete' : 'valid';
lead.data_quality = {
  is_complete: validationStatus === 'valid',
  missing_fields: [...missing, ...invalid],
  validation_status: validationStatus
};
lead.processing.updated_at = new Date().toISOString();
lead.audit_events = Array.isArray(lead.audit_events) ? lead.audit_events : [];
if (validationStatus !== 'valid') {
  lead.audit_events.push({
    lead_id: lead.lead_id ?? null,
    event_type: 'validation_failed',
    workflow_name: 'WF02_validation_identity',
    execution_id: $execution.id,
    payload: { validation_status: validationStatus, fields: lead.data_quality.missing_fields },
    created_at: new Date().toISOString()
  });
} else {
  lead.audit_events.push({
    lead_id: lead.lead_id ?? null,
    event_type: 'data_completed',
    workflow_name: 'WF02_validation_identity',
    execution_id: $execution.id,
    payload: { validation_status: 'valid' },
    created_at: new Date().toISOString()
  });
}
return [{ json: lead }];

