const incoming = JSON.parse(JSON.stringify($json.incoming_lead ?? {}));
const candidates = Array.isArray($json.candidates) ? $json.candidates : [];
const norm = (value) => value == null ? '' : String(value).trim().toLowerCase().replace(/\s+/g, ' ');
const same = (a, b) => Boolean(norm(a) && norm(a) === norm(b));
const differs = (a, b) => Boolean(norm(a) && norm(b) && norm(a) !== norm(b));
const closeInTime = (a, b) => {
  const first = Date.parse(a ?? '');
  const second = Date.parse(b ?? '');
  return Number.isFinite(first) && Number.isFinite(second) && Math.abs(first - second) <= 2 * 60 * 1000;
};

let best = null;
for (const candidate of candidates) {
  const phoneMatch = same(incoming.contact?.phone_normalized, candidate.phone_normalized);
  const emailMatch = same(incoming.contact?.email_normalized, candidate.email_normalized);
  const nameMatch = same(incoming.contact?.name, candidate.name);
  const companyMatch = same(incoming.business?.company_name, candidate.company_name);
  const differentSource = Boolean(norm(incoming.source?.type) && norm(candidate.source) && norm(incoming.source?.type) !== norm(candidate.source));
  const timeMatch = closeInTime(incoming.source?.received_at, candidate.received_at);
  const serviceMatch = same(incoming.business?.service_interest, candidate.service_interest);
  const phoneConflict = differs(incoming.contact?.phone_normalized, candidate.phone_normalized);
  const emailConflict = differs(incoming.contact?.email_normalized, candidate.email_normalized);
  const seriousConflict = (phoneMatch && emailConflict) || (emailMatch && phoneConflict);
  const exactContactMatch = (phoneMatch || emailMatch) && !seriousConflict;
  const contextualScore =
    (nameMatch ? 0.3 : 0) +
    (companyMatch ? 0.2 : 0) +
    (differentSource ? 0.1 : 0) +
    (timeMatch ? 0.2 : 0) +
    (serviceMatch ? 0.1 : 0);
  const contextualConfidence = Math.min(1, Math.round(contextualScore * 10) / 10);
  const confidence = exactContactMatch ? 1 : contextualConfidence;
  const scored = {
    candidate,
    confidence,
    contextualConfidence,
    phoneMatch,
    emailMatch,
    nameMatch,
    companyMatch,
    differentSource,
    timeMatch,
    serviceMatch,
    seriousConflict,
    exactContactMatch
  };
  if (!best || Number(scored.exactContactMatch) > Number(best.exactContactMatch) ||
      (scored.exactContactMatch === best.exactContactMatch && scored.confidence > best.confidence)) {
    best = scored;
  }
}

let status = 'unique';
if (best?.exactContactMatch) status = 'exact_duplicate';
else if (best && best.contextualConfidence >= 0.6) status = 'likely_duplicate';

const reason = !best
  ? 'no_identity_candidate'
  : `phone=${best.phoneMatch};email=${best.emailMatch};name=${best.nameMatch};company=${best.companyMatch};different_source=${best.differentSource};within_2_minutes=${best.timeMatch};service=${best.serviceMatch};serious_conflict=${best.seriousConflict}`;

incoming.identity = {
  status,
  matched_lead_id: best?.candidate?.id ?? null,
  confidence: best?.confidence ?? 0
};
incoming.processing = { ...(incoming.processing ?? {}), updated_at: new Date().toISOString() };
incoming.audit_events = Array.isArray(incoming.audit_events) ? incoming.audit_events : [];
if (status !== 'unique') incoming.audit_events.push({
  lead_id: incoming.lead_id ?? null,
  event_type: 'duplicate_detected',
  workflow_name: 'WF02_validation_identity',
  execution_id: $execution.id,
  payload: { status, confidence: incoming.identity.confidence, matched_lead_id: incoming.identity.matched_lead_id, reason },
  created_at: new Date().toISOString()
});

if (status === 'exact_duplicate' && best) {
  const candidateLeadId = incoming.lead_id;
  const existing = best.candidate;
  const prefer = (current, fallback) => current !== null && current !== undefined && current !== '' ? current : fallback;
  incoming.lead_id = existing.id;
  incoming.source = {
    type: prefer(existing.source, incoming.source?.type),
    external_id: prefer(existing.external_source_id, incoming.source?.external_id),
    received_at: prefer(existing.received_at, incoming.source?.received_at)
  };
  incoming.contact = {
    ...incoming.contact,
    name: prefer(existing.name, incoming.contact?.name),
    phone_raw: prefer(existing.phone_raw, incoming.contact?.phone_raw),
    phone_normalized: prefer(existing.phone_normalized, incoming.contact?.phone_normalized),
    email_raw: prefer(existing.email_raw, incoming.contact?.email_raw),
    email_normalized: prefer(existing.email_normalized, incoming.contact?.email_normalized),
    consent: existing.consent === true || incoming.contact?.consent === true
  };
  incoming.business = {
    ...incoming.business,
    company_name: prefer(existing.company_name, incoming.business?.company_name),
    service_interest: prefer(existing.service_interest, incoming.business?.service_interest),
    country: prefer(existing.country, incoming.business?.country),
    industry: prefer(existing.industry, incoming.business?.industry),
    company_size: prefer(existing.company_size, incoming.business?.company_size),
    strategic_account: existing.strategic_account === true || incoming.business?.strategic_account === true
  };
  incoming.request = { ...incoming.request, message: prefer(existing.message, incoming.request?.message) };
  incoming.identity = { status: 'exact_duplicate', matched_lead_id: existing.id, confidence: 1 };
  incoming.duplicate_decision = {
    candidate_lead_id: candidateLeadId,
    matched_lead_id: existing.id,
    match_type: best.phoneMatch && best.emailMatch ? 'exact_phone_and_email' : best.phoneMatch ? 'exact_phone' : 'exact_email',
    confidence: 1,
    decision: 'merge_missing_fields',
    reason,
    created_at: new Date().toISOString()
  };
}

if (status === 'likely_duplicate' && best) incoming.duplicate_decision = {
  candidate_lead_id: incoming.lead_id,
  matched_lead_id: best.candidate.id,
  match_type: 'likely_identity',
  confidence: best.contextualConfidence,
  decision: 'manual_review',
  reason,
  created_at: new Date().toISOString()
};
return [{ json: incoming }];

